// ---- chapter 66: distributed SQL ---------------------------------------
// Downloads the pinned YugabyteDB archive from software.yugabyte.com into .yugabyte/ and checks its SHA-256. No AWS. Starts nothing.
"distsql:fetch": fresh("node scripts/fetch.ts", { cwd: "examples/66-distributed-sql" }),
// A certificate authority and a certificate for 127.0.0.1 in .yugabyte/. Needs openssl on PATH.
"distsql:local:certs": fresh("node scripts/certs.ts", { cwd: "examples/66-distributed-sql" }),
// Three nodes on 127.0.0.1 (ports 23001-29103), as detached processes. `--tls` on a new cluster.
"distsql:local:start": fresh("node scripts/cluster.ts start", { cwd: "examples/66-distributed-sql" }),
"distsql:local:status": fresh("node scripts/cluster.ts status", { cwd: "examples/66-distributed-sql" }),
// SIGKILL to both processes of one node: `vp run distsql:local:kill b`.
"distsql:local:kill": fresh("node scripts/cluster.ts kill", { cwd: "examples/66-distributed-sql" }),
"distsql:local:stop": fresh("node scripts/cluster.ts stop", { cwd: "examples/66-distributed-sql" }),
// Stops every node and deletes .yugabyte/run.
"distsql:local:destroy": fresh("node scripts/cluster.ts destroy", { cwd: "examples/66-distributed-sql" }),
// Chapter 13's migrations and repository on the local cluster, a real conflict, one node killed, two nodes killed, a dump restored.
"distsql:local:verify": fresh("node scripts/verify.ts", { cwd: "examples/66-distributed-sql" }),
// Fails when deploy/ differs from what the generators produce. `--write` rewrites it.
"distsql:render": fresh("node scripts/render.ts", { cwd: "examples/66-distributed-sql" }),
// With `-c nodes=3`: three instances and their volumes, billed by the hour.
...infra("distsql", "examples/66-distributed-sql", "AihDistSql"),
// Everything below goes through Systems Manager to the deployed nodes.
"distsql:status": live("node --env-file-if-exists=../../.env scripts/nodes.ts status", { cwd: "examples/66-distributed-sql" }),
"distsql:logs": live("node --env-file-if-exists=../../.env scripts/nodes.ts logs", { cwd: "examples/66-distributed-sql" }),
"distsql:health": live("node --env-file-if-exists=../../.env scripts/nodes.ts health", { cwd: "examples/66-distributed-sql" }),
// Uploads the archive that `distsql:fetch --nodes` downloaded.
"distsql:artifact": live("node --env-file-if-exists=../../.env scripts/nodes.ts artifact", { cwd: "examples/66-distributed-sql" }),
"distsql:install": live("node --env-file-if-exists=../../.env scripts/nodes.ts install", { cwd: "examples/66-distributed-sql" }),
// Each node makes its key; the CA in .yugabyte/ca-aws signs the request. Needs openssl on PATH.
"distsql:certs": live("node --env-file-if-exists=../../.env scripts/nodes.ts certs", { cwd: "examples/66-distributed-sql" }),
"distsql:configure": live("node --env-file-if-exists=../../.env scripts/nodes.ts configure", { cwd: "examples/66-distributed-sql" }),
"distsql:start": live("node --env-file-if-exists=../../.env scripts/nodes.ts start", { cwd: "examples/66-distributed-sql" }),
// One node: `vp run distsql:stop b`.
"distsql:stop": live("node --env-file-if-exists=../../.env scripts/nodes.ts stop", { cwd: "examples/66-distributed-sql" }),
// An interactive shell on one node. Needs the Session Manager plugin.
"distsql:session": live("node --env-file-if-exists=../../.env scripts/nodes.ts session", { cwd: "examples/66-distributed-sql" }),
